from pathlib import Path
import html, json, markdown
ROOT=Path(__file__).resolve().parent
sections=[]
for filename in ['options-menu.md','review.md']:
    p=ROOT/filename
    if p.exists(): sections.append(markdown.markdown(p.read_text(),extensions=['tables']))
sections.append('<h1>Reusable assistant instructions</h1><p>Copied unchanged from the SNHU mission and saved in the project.</p><pre>'+html.escape((ROOT/'assistant-instructions.txt').read_text())+'</pre>')
for p in sorted((ROOT/'transcripts').glob('*.txt')):
    sections.append('<h1>Transcript: '+html.escape(p.stem)+'</h1><pre>'+html.escape(p.read_text())+'</pre>')
