(ROOT/'UDL-Planning-Portfolio.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>UDL Planning Portfolio</title><style>'+css+'</style></head><body>'+body+'</body></html>')
# Cover is an actual rendered excerpt of the reviewed options-menu table.
menu=markdown.markdown((ROOT/'options-menu.md').read_text(),extensions=['tables'])
table=menu[menu.index('<table>'):menu.index('</table>')+8]
